    const int TILE_DIM = 32; // Increased block size for better occupancy and shared memory utilization

    // Shared memory for tiles of A and B
    __shared__ float sA[TILE_DIM][TILE_DIM];
    __shared__ float sB[TILE_DIM][TILE_DIM];

    // Global indices of the current thread
    int row = blockIdx.y * TILE_DIM + threadIdx.y;
    int col = blockIdx.x * TILE_DIM + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load tiles from global memory to shared memory
        int a_global_row = row;
        int a_global_col = t * TILE_DIM + threadIdx.x;
        if (a_global_row < N && a_global_col < N) {
            sA[threadIdx.y][threadIdx.x] = A[a_global_row * N + a_global_col];
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if out of bounds
